static __global__ void __launch_bounds__(128)
kg_gemv(const uint8_t *__restrict__ W, const uint8_t *__restrict__ X, float *__restrict__ Y, int N, int K, int M) {
  __shared__ uint32_t tab[512];
  for (int i = threadIdx.x; i < 512; i += blockDim.x) tab[i] = kE8P[i];
  __syncthreads();
  const int lr = threadIdx.x / 32, lid = threadIdx.x % 32;
  const int row = blockIdx.x * 4 + lr, wrow = row < N ? row : N - 1;
  const int col0 = blockIdx.y * COLS;
  const uint8_t *wq = W + (size_t)wrow * ((size_t)K * 8 / 32);
  const uint8_t *ws = W + (size_t)N * ((size_t)K * 8 / 32) + (size_t)wrow * ((size_t)K / 256 * 2);
  const uint8_t *xr[COLS];
  float acc[COLS];
  #pragma unroll
  for (int j = 0; j < COLS; j++) { xr[j] = X + (size_t)min(col0 + j, M - 1) * ((size_t)K / 256 * 292); acc[j] = 0.f; }
  const int work = K / 32 * SUB;
  for (int w0 = lid; w0 < work; w0 += 64) {
    #pragma unroll
    for (int k = 0; k < 2; k++) {
      const int w = w0 + k * 32;
      if (w < work) kunit(wq, ws, w / SUB, w % SUB, xr, acc, tab);
    }
  }
  #pragma unroll
  for (int j = 0; j < COLS; j++) {
    float v = acc[j];
    v += __shfl_xor_sync(KURN_FULL, v, 16);
    v += __shfl_xor_sync(KURN_FULL, v, 8);
    v += __shfl_xor_sync(KURN_FULL, v, 4);
    v += __shfl_xor_sync(KURN_FULL, v, 2);
    v += __shfl_xor_sync(KURN_FULL, v, 1);
    if (lid == 0 && row < N && col0 + j < M) Y[(size_t)(col0 + j) * N + row] = v;
  }
}

