  uint8_t *q = P + (size_t)r * ((size_t)K * 8 / 32) + (size_t)bl * 64;
  uint8_t *s = P + (size_t)N * ((size_t)K * 8 / 32) + (size_t)r * ((size_t)K / 256 * 2) + (size_t)bl * 2;
  for (int ch = 0; ch < 8; ch++) for (int i = 0; i < 4; i++) { q[8 * ch + i] = src[2 + 4 * ch + i]; q[8 * ch + 4 + i] = src[34 + 4 * ch + i]; }
  s[0] = src[0]; s[1] = src[1];
}

extern "C" {
const char *kg_config(void) { return "op=gemv weights=e8p arch=sm_80 layout=split tpr=32 rpb=4 sub=4 unroll=2 cols=1 minb=0 mins=none unpack=none"; }
int kg_check_shape(int N, int K, int M) { return (N > 0 && M > 0 && K > 0 && K % 256 == 0) ? 0 : -1; }
size_t kg_prep_bytes(int N, int K) { (void)N; (void)K; return (size_t)N * (((size_t)K * 8 / 32) + ((size_t)K / 256 * 2)); }
size_t kg_xbytes(int K, int M) { return (size_t)M * ((size_t)K / 256 * 292); }
int kg_prepare(const void *W, void *Wp, int N, int K, cudaStream_t s) {
  const long nblk = (long)N * (K / 256);
  KURN_LAUNCH(kg_repack, dim3((unsigned)((nblk + 127) / 128)), dim3(128), s, (const uint8_t *)W, (uint8_t *)Wp, N, K);
#ifdef KURN_EMU
  return 0;
#else
  return (int)cudaGetLastError();
#endif
}
int kg_quant(const float *X, void *Xq, int K, int M, cudaStream_t s) {
  KURN_LAUNCH(kg_quant_q8_K, dim3((unsigned)(((long)M * (K / 256) + 3) / 4)), dim3(128), s, X, (uint8_t *)Xq, K, M);
#ifdef KURN_EMU
  return 0;
#else
  return (int)cudaGetLastError();
#endif
}
size_t kg_xblock_bytes(int K, int M) { return (size_t)M * (K / 256) * 292; }
int kg_xblocks(const float *X, void *Xb, int K, int M, cudaStream_t s) {
  KURN_LAUNCH(kg_quant_q8_K, dim3((unsigned)(((long)M * (K / 256) + 3) / 4)), dim3(128), s, X, (uint8_t *)Xb, K, M);
#ifdef KURN_EMU
  return 0;
#else
  return (int)cudaGetLastError();
#endif
}
int kg_run(const void *W, const void *Xq, float *Y, int N, int K, int M, cudaStream_t s) {
  if (kg_check_shape(N, K, M)) return -1;
  KURN_LAUNCH(kg_gemv, dim3((unsigned)((N + 4 - 1) / 4), (unsigned)((M + 1 - 1) / 1)), dim3(128), s, (const uint8_t *)W, (const uint8_t *)Xq, Y, N, K, M);
#ifdef KURN_EMU
  return 0;
#else
  return (int)cudaGetLastError();
#endif
}
}
